}
export function nobleBodyChoiceTargets(
  world: World,
  day: number,
  kind: "body" | "noble",
): readonly number[] {
  const { owner, night } = requireNight(world, day);
  if (
    !(kind === "body" ? night.requiresBody : night.requiresNoble) ||
    !playerCurrent(world, owner[kind], true)
