    "policy",
    "awakenedDay",
    "knownTeammateIds",
    "extraRemaining",
    "extraHistory",
  ]);
  if (!r || r.policy !== MIST_RAVEN_POLICY || (r.awakenedDay !== null && !positive(r.awakenedDay)))
    return;
